type point = (int, int);

type shape =
  | Circle(point, int)
  | Rect(point, point);

/** Twice the area, so everything stays in integers. */
let area = (s: shape): int =>
  switch (s) {
  | Circle(_, r) => 6 * r * r
  | Rect((x0, y0), (x1, y1)) => 2 * abs(x1 - x0) * abs(y1 - y0)
  };

edit.new:
  | Rect((x0, y0), (x1, y1)) => 2 * abs(x1 - x0) * abs(y1 - y0)
  };

let translate = ((dx, dy): point, s: shape): shape => {
  let move = ((x, y)) => (x + dx, y + dy);
  switch (s) {
  | Circle(c, r) => Circle(move(c), r)
  | Rect(a, b) => Rect(move(a), move(b))
  };
};

let scale = (k: int, s: shape): shape =>
  switch (s) {
  | Circle(c, r) => Circle(c, k * r)
  | Rect(a, (x1, y1)) => Rect(a, (k * x1, k * y1))
  };

type scene = list(shape);

let total_area = (sc: scene): int =>
  List.fold_left((acc, s) => acc + area(s), 0, sc);
